mapper.select:
SELECT bsa.*,ba.auxiliary_type_id,concat(ba.`code`,' ',ba.`name`) auxiliaryNameBy  FROM `book_subject_auxiliary` bsa
LEFT JOIN book_auxiliary ba ON bsa.auxiliary_id = ba.auxiliary_id
where bsa.del_flag = '0'

    and ba.auxiliary_type_id = #{auxiliaryTypeId}


    and bsa.subject_id = #{subjectId}

SELECT IFNULL(SUM(bsa.balance),0) balance,IFNULL(SUM(bsa.credit),0) credit,IFNULL(SUM(bsa.debit),0) debit from book_subject_auxiliary bsa
LEFT JOIN book_auxiliary ba ON bsa.auxiliary_id = ba.auxiliary_id
WHERE bsa.del_flag = '0'

    and bsa.subject_id = #{subjectId}


    and ba.auxiliary_type_id = #{auxiliaryTypeId}


    and bsa.auxiliary_id = #{auxiliaryId}
